contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount, interest, loanToCollateral, duration
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "loanToCollateral must be nonzero");
        // We act as msg.sender when calling c; the test contract must hold enough collateral token
        // However we cannot mint tokens here; instead we rely on the checker-provided fresh deployment
        // and only assert a general relation when requestLoan does not revert.

        // Record request count before
        uint256 beforeLen = c.requestsLength();

        bool reverted;
        // Call requestLoan and catch revert
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After-call observations we are allowed: requests length, isActive, getRequest
        uint256 afterLen = c.requestsLength();

        // If call reverted, then nothing required about state; assert that if it reverted no new request was added
        if (reverted) {
            assert(afterLen == beforeLen);
        } else {
            // If not reverted, exactly one new request should be appended and it should be active and store the requested amount
            assert(afterLen == beforeLen + 1);
            uint256 reqID = beforeLen;
            C.Request memory req = c.getRequest(reqID);
            assert(req.active && req.amount == amount_);
        }
    }

    receive() external payable {}
 }

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount, interest, loanToCollateral, duration
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        // loanToCollateral_ must be nonzero to avoid divide-by-zero in collateralFor when external transfers might occur
        require(loanToCollateral_ != 0);

        // observe requests length before by using the public getter pattern: call getRequest in a loop until it reverts or we reach a sentinel
        // but looping with calls that may revert is unsafe. Instead, use behavior of public array: reading one past end reverts, so we find length by binary probing is complex.
        // Simpler: try to read requests at successive indices until a revert to determine length (works within gas limits for small lengths that checker uses).
        uint256 beforeLen = 0;
        while (true) {
            // stop if too large to avoid running out of gas in solver; cap to a reasonable bound
            if (beforeLen >= 10) break;
            try c.getRequest(beforeLen) returns (C.Request memory) {
                beforeLen++;
            } catch {
                break;
            }
        }

        bool reverted;
        // attempt the mutating call
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // compute after length similarly
        uint256 afterLen = 0;
        while (true) {
            if (afterLen >= 11) break; // one more than before probe cap
            try c.getRequest(afterLen) returns (C.Request memory) {
                afterLen++;
            } catch {
                break;
            }
        }

        if (reverted) {
            // if the call reverted, no new request must have been appended (length unchanged)
            assert(afterLen == beforeLen);
        } else {
            // if call succeeded, exactly one new request appended
            assert(afterLen == beforeLen + 1);
            uint256 reqID = beforeLen;
            C.Request memory req = c.getRequest(reqID);
            // and its stored amount equals input amount and it's active
            assert(req.amount == amount_ && req.active == true);
        }
    }

    receive() external payable {}
}

