        require(loanToCollateral_ != 0);

        // determine requests length before by probing up to a small bound
        uint256 beforeLen = 0;
        while (beforeLen < 16) {
            try c.getRequest(beforeLen) returns (C.Request memory) {
                beforeLen++;
            } catch {
                break;
            }
        }

        bool reverted;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // determine requests length after by probing up to bound
        uint256 afterLen = 0;
        while (afterLen < 17) {
            try c.getRequest(afterLen) returns (C.Request memory) {
                afterLen++;
            } catch {
                break;
            }
        }

        // Single assert expressing the general invariant:
        // if the call reverted then length unchanged; else length increased by 1 and the new request's amount equals amount_ and is active
