contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to create a request and then call clearRequest from this contract (as a lender).
    // Preconditions: loanToCollateral non-zero to avoid division by zero in collateralFor; duration reasonable.
    function run(uint256 reqAmount, uint256 reqInterest, uint256 loanToCollateral, uint256 duration) public payable {
        require(loanToCollateral != 0);

        // First, create a request by calling requestLoan as this contract (msg.sender for requestLoan will be this contract)
        // We must ensure collateral transfer succeeds: collateral().safeTransferFrom(msg.sender, address(this), ...) in requestLoan
        // But since this contract has no tokens, requestLoan will usually revert due to transferFrom failing.
        // To avoid interacting with tokens, instead we will rely on the behavior of clearRequest when a prior request exists.
        // So we call requestLoan and record whether it reverted. If it reverted, then clearRequest cannot succeed later.

        bool reqReverted;
        uint256 reqID;
        try c.requestLoan(reqAmount, reqInterest, loanToCollateral, duration) returns (uint256 r) {
            reqReverted = false;
            reqID = r;
        } catch {
            reqReverted = true;
            // If request creation reverted, we cannot proceed to clearRequest successfully, so assert will allow that.
        }

        bool clearReverted;
        uint256 loanID;
        // Attempt to clear the request by calling clearRequest from this contract (acting as lender)
        try c.clearRequest(reqID, false, false) returns (uint256 lid) {
            clearReverted = false;
            loanID = lid;
        } catch {
            clearReverted = true;
        }

        // If clearRequest succeeded (did not revert), then observable loan at loanID must have lender == address(this)
        // and loan.amount >= original request.amount (principal + interest >= principal). We fetch the loan via getLoan.
        C.Loan memory loan;
        if (!clearReverted) {
            loan = c.getLoan(loanID);
        }

        assert(clearReverted || (loan.lender == address(this) && loan.amount >= loan.request.amount));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We take parameters to drive requestLoan and rescindRequest. We model two actors by using
    // this contract as caller for both calls (the checker deploys c with this as deployer).
    // amount_, interest_, loanToCollateral_, duration_, reqIDToRescind are arbitrary inputs.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, uint256 reqIDToRescind) public payable {
        require(loanToCollateral_ != 0, "loanToCollateral nonzero");

        // Precondition: ensure this contract has enough collateral tokens to transfer into c.
        // We cannot mint tokens here; but the test environment provides the initial token balances
        // reachable by calls. We cannot call internal/mint, so we conservatively proceed.
        // Call requestLoan: this will attempt to transfer collateral from msg.sender (this) to c.
        bool revertedRequest;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            revertedRequest = false;
        } catch {
            revertedRequest = true;
        }

        // Observe whether the request was created and whether it is active, if not reverted.
        // If requestLoan succeeded, a new request is appended at index (requests.length-1).
        // We can fetch isActive at index reqIDToRescind to reason about rescind.

        bool revertedRescind;
        // Attempt rescindRequest only if this contract is owner() of c; otherwise it must revert.
        address owner = c.owner();
        if (owner == address(this)) {
            try c.rescindRequest(reqIDToRescind) {
                revertedRescind = false;
            } catch {
                revertedRescind = true;
            }
        } else {
            // If not owner, calling rescind would revert; simulate that by setting flag accordingly.
            revertedRescind = true;
        }

        // Read observable state: isActive for reqIDToRescind (may revert if out of bounds), and contract balance
        bool activeObserved;
        bool activeReadable = true;
        try c.isActive(reqIDToRescind) returns (bool a) {
            activeObserved = a;
        } catch {
            // cannot read (out of bounds) — mark as not readable
            activeReadable = false;
            activeObserved = false;
        }

        // The property: If requestLoan succeeded and produced a request (i.e., not revertedRequest),
        // then isActive for some request index must be true (there exists at least one active request).
        // Also, if this contract is owner and rescindRequest did NOT revert, then either: rescindRequest call
        // deactivated that specific request (isActive(reqIDToRescind) == false if readable) and rescind did not revert;
        // conversely, if rescindRequest reverted then isActive stays true (if readable). We express a conservative
        // general rule combining these facts into one assert.

        // Build the assertion:
        // - If requestLoan did not revert then there must exist at least one active request: we check that
        //   if any readable request index equals the last index we conservatively verify that either the
        //   observed reqIDToRescind is active or rescind succeeded deactivating it. Because we cannot enumerate
        //   all requests, we assert a weaker but general relation between the two operations:
        //   If requestLoan succeeded and owner==address(this) and rescindRequest succeeded, then the observed
        //   isActive(reqIDToRescind) must be false (if readable). If requestLoan succeeded and rescindRequest reverted
        //   (or owner!=this), then if readable the isActive value must be unchangedly true.

        // We express this: (A => B) where A = (not revertedRequest && owner==address(this) && not revertedRescind && activeReadable)
        // and B = (activeObserved == false). Additionally, (C => D) where C = (not revertedRequest && activeReadable && (owner!=address(this) || revertedRescind))
        // and D = (activeObserved == true).

        bool part1 = (!revertedRequest && owner == address(this) && !revertedRescind && activeReadable) ? (activeObserved == false) : true;
        bool part2 = (!revertedRequest && activeReadable && (owner != address(this) || revertedRescind)) ? (activeObserved == true) : true;

        assert(part1 && part2);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: inputs to create a request and an index to rescind. payable in case token transfers in tested env use ETH-like tokens.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, uint256 reqID) public payable {
        // loanToCollateral_ must be non-zero to avoid div-by-zero in collateralFor when requestLoan executes.
        require(loanToCollateral_ != 0);

        // Attempt to create a request as this contract (msg.sender == address(this)). Capture whether it reverted.
        bool createdReverted;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            createdReverted = false;
        } catch {
            createdReverted = true;
        }

        // Read owner to know who is allowed to rescind.
        address owner = c.owner();

        // Attempt rescindRequest unconditionally and capture revert status.
        bool rescindReverted;
        try c.rescindRequest(reqID) {
            rescindReverted = false;
        } catch {
            rescindReverted = true;
        }

        // Try to read isActive for the given reqID. If out-of-bounds this will revert; treat that as unreadable.
        bool activeReadable = true;
        bool activeVal = false;
        try c.isActive(reqID) returns (bool v) {
            activeVal = v;
        } catch {
            activeReadable = false;
        }

        // General rule asserted:
        // If rescindRequest succeeded (did not revert) then the caller must have been owner and the request must now be inactive (if readable).
        // If rescindRequest reverted and the caller was NOT owner, then the request (if readable) remains active (== true).
        // We only assert these implications when the request creation did not itself revert (otherwise request may not exist).

        bool rule1 = true;
        if (!createdReverted && !rescindReverted) {
            // rescind succeeded: caller must be owner and, if readable, isActive(reqID) == false
            rule1 = (owner == address(this));
            if (activeReadable) rule1 = rule1 && (activeVal == false);
        }

        bool rule2 = true;
        if (!createdReverted && rescindReverted && owner != address(this)) {
            // non-owner attempted rescind and it reverted: if readable the request should remain active
            if (activeReadable) rule2 = (activeVal == true);
        }

        assert(rule1 && rule2);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: prepare a request as this contract then call clearRequest as a caller provided by parameter `asCallback`.
    // We use reqID to pick the request index we create (it will be the next index). No ETH involved.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_, bool isCallback_) public payable {
        // require loanToCollateral_ non-zero to avoid division by zero in collateralFor
        require(loanToCollateral_ != 0);

        // Create a request as this contract (msg.sender == address(this)). If requestLoan reverts, we cannot proceed.
        bool createdReverted = false;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            createdReverted = false;
        } catch {
            createdReverted = true;
        }

        // If creation reverted, we cannot assert properties about the created request/loan; so require it succeeded.
        require(!createdReverted);

        // The request we just created will have id = c.getRequestCount()-1, but there is no getter for count. Instead
        // we rely on behavior that requests are appended: we choose reqID = 0 and read isActive; to be robust, read owner and
        // attempt clearRequest on the most-recent request by trying increasing indices would be complex. Simpler: assume the
        // new request is at index 0 when run on fresh contract deployment by the harness (checker deploys fresh c). To be
        // safe against other states, we instead scan a small range [0..3] to find an active request we can clear.

        uint256 foundReq = type(uint256).max;
        for (uint256 i = 0; i < 4; i++) {
            // Try reading isActive(i). If it reverts (out of bounds) skip.
            bool ok;
            bool active;
            try c.isActive(i) returns (bool v) {
                ok = true;
                active = v;
            } catch {
                ok = false;
                active = false;
            }
            if (ok && active) { foundReq = i; break; }
        }

        // We must have found an active request to clear; otherwise contract state doesn't permit clearRequest here.
        require(foundReq != type(uint256).max);

        // Now call clearRequest as this contract (msg.sender) — capture whether it reverts.
        bool clearedReverted;
        try c.clearRequest(foundReq, repayDirect_, isCallback_) returns (uint256 loanID) {
            clearedReverted = false;
        } catch {
            clearedReverted = true;
        }

        // We only assert the general rule when clearRequest succeeded.
        require(!clearedReverted);

        // Now find the newest loan that corresponds to the created loan. We'll scan loans 0..7 to find one whose lender == address(this).
        // We observe loans via getLoan; if out-of-bounds, getLoan will revert and we skip.
        bool foundLoan = false;
        uint256 foundLoanID = 0;
        C.Loan memory loan;
        for (uint256 j = 0; j < 8; j++) {
            try c.getLoan(j) returns (C.Loan memory L) {
                if (L.lender == address(this)) {
                    foundLoan = true;
                    foundLoanID = j;
                    loan = L;
                    break;
                }
            } catch {
                // skip invalid indices
            }
