        // If clearRequest created a loan from the previously observed request, then that request is inactive,
        // the loan's lender is this contract (the caller of clearRequest) and loan.amount >= request.amount.
        assert(!loanCreated || (createdReqID != type(uint256).max && reqActive == false && loan.lender == address(this) && loan.amount >= req.amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function holding all test logic
    // We take parameters for the request to create. loanToCollateral_ must be non-zero to avoid division by zero in collateralFor.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0);

        // Attempt to create a request. This may revert due to ERC20 transferFrom; capture revert.
        bool reqReverted;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            reqReverted = false;
        } catch {
            reqReverted = true;
        }

        // If request creation reverted, we can't proceed to clear it; in that case, require the assertion to be vacuously true by asserting reqReverted.
        if (reqReverted) {
            // If request creation reverted, then clearRequest can't succeed on that request created here, so assert true via requiring reqReverted.
            assert(reqReverted);
            return;
        }

        // If request succeeded, the new request will be at some index. The contract's request IDs start at 0 and increase by 1 each creation.
        // We will probe a small range to find a matching request. Limit to 8 indices to keep the test simple.
        uint256 foundReq = type(uint256).max;
        for (uint256 i = 0; i < 8; i++) {
            // getRequest is public view; call and compare fields. Use try in case index out of range.
            try c.getRequest(i) returns (C.Request memory r) {
                if (r.amount == amount_ && r.interest == interest_ && r.loanToCollateral == loanToCollateral_ && r.duration == duration_) {
                    foundReq = i;
                    break;
                }
            } catch {
                // continue probing
            }
        }

        // If we couldn't find the request within the probe bound, require failure (so assertion remains non-trivial).
        require(foundReq != type(uint256).max);

        // Now attempt to clear that request as this contract (msg.sender == address(this)). Capture whether clearRequest reverted.
        bool clearReverted;
        try c.clearRequest(foundReq, false, false) returns (uint256 loanID) {
            clearReverted = false;
            // If clear succeeded, verify the created loan's lender equals this contract in the final assert below using loanID.
            // Store loanID in a temporary slot by writing to storage via a local variable (we will read via getLoan in assertion part).
            // But since we cannot store it persistently across flows, we will read the loan assuming it's the last loan: probe for loans to find one whose request.amount matches amount_.
        } catch {
            clearReverted = true;
        }

        if (clearReverted) {
            // If clear reverted, then nothing to assert about lender; assert that clear did revert.
            assert(clearReverted);
            return;
        }

        // After successful clear, find a loan created that matches the original request.amount (loan.request.amount == amount_).
        uint256 foundLoan = type(uint256).max;
        for (uint256 j = 0; j < 8; j++) {
            try c.getLoan(j) returns (C.Loan memory L) {
                if (L.request.amount == amount_ && L.lender == address(this)) {
                    foundLoan = j;
                    break;
                }
            } catch {
                // continue
            }
        }

        // Final general assertion: if clearRequest did not revert then there exists a loan (within probe) whose lender is this contract.
        assert(foundLoan != type(uint256).max);
    }

    receive() external payable {}
}

