contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: create a request first (amount, interest, loanToCollateral, duration),
    // then caller (this contract) will call clearRequest on that reqID.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_, bool isCallback_) public payable {
        // Precondition: ensure collateral decimals division won't revert by using non-zero loanToCollateral_
        require(loanToCollateral_ != 0, "loanToCollateral nonzero");

        // First, the external owner must be msg.sender of requestLoan. In this setup, the InvMutTest contract is msg.sender
        // So we call requestLoan to create a request indexed at reqID = 0 (since fresh c)
        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        // Read that it is active before clearing
        bool activeBefore = c.isActive(reqID);

        // Now attempt to clearRequest from this contract (msg.sender == this contract)
        bool reverted;
        uint256 loanID;
        try c.clearRequest(reqID, repayDirect_, isCallback_) returns (uint256 id) {
            reverted = false;
            loanID = id;
        } catch {
            reverted = true;
        }

        // Observables after call
        bool activeAfter = c.isActive(reqID);
        // If clearRequest succeeded, it should have created a loan with lender == msg.sender (this contract)
        // We can fetch the loan and read lender via getLoan
        C.Loan memory loan; // use type from c's ABI via C
        if (!reverted) {
            loan = c.getLoan(loanID);
        }

        // General rule: if the clearRequest call did not revert, then activeBefore must have been true,
        // activeAfter must be false, and the loan.lender must equal address(this).
        assert(reverted || (activeBefore && !activeAfter && loan.lender == address(this)));
    }

    receive() external payable {}
}

