        C.Request memory req = c.getRequest(reqID);
        C.Loan memory loan = cleared ? c.getLoan(loanID) : C.Loan({ request: C.Request({ amount: 0, interest: 0, loanToCollateral: 0, duration: 0, active: false }), amount: 0, unclaimed: 0, collateral: 0, expiry: 0, lender: address(0), repayDirect: false, callback: false });

